## 4. Verification

### 4.1 Run

```bash
node solve.js trace_a.json
```

Observed result (exact, key fields):

```json
{
  "finalCwnd": 2,
  "finalSsthresh": 2,
  "scoreboardHoles": [[6, 7]],
  "scoreboard": [[5, 6], [7, 8]],
  "spuriousRetransmits": [
    { "seq": 1, "detectedAt": 20, "reason": "Eifel",
      "retxAt": 10, "originalSentAt": 1, "tsEcho": 1,
      "before": { "cwnd": 2, "ssthresh": 2 },
      "restored": { "cwnd": 5, "ssthresh": 8 } },
    { "seq": 6, "detectedAt": 55, "reason": "DSACK",
      "retxAt": 52, "originalSentAt": 42, "tsEcho": 42,
      "before": { "cwnd": 2, "ssthresh": 2 },
      "restored": { "cwnd": 6, "ssthresh": 8 } }
  ],
  "lostSegments": [
    { "t": 10, "seq": 1 }, { "t": 50, "seq": 3 },
    { "t": 50, "seq": 5 }, { "t": 65, "seq": 5 }
  ],
  "minRtt": 10,
  "reoWnd": 2.5,
  "sndUna": 6,
  "sndNxt": 8,
  "inRecovery": true
