'use strict';
const assert = require('assert');
const fs = require('fs');
const { TcpSackRack, norm, subIv, gapsIv } = require('./solve.js');

let passed = 0;
function test(name, fn) {
  try { fn(); passed++; console.log('ok   - ' + name); }
  catch (e) { console.log('FAIL - ' + name + '\n       ' + e.message); process.exitCode = 1; }
}
const run = (trace) => new TcpSackRack(trace.config || {}).run(trace);
const base = (events, segments, config) => ({ config, segments, events });
const segs = (n, t0 = 0) => Array.from({ length: n }, (_, i) => ({ seq: i, len: 1, sentAt: t0 + i }));

test('norm merges overlapping and adjacent intervals', () =>
  assert.deepStrictEqual(norm([[3, 4], [1, 2], [2, 3]]), [[1, 4]]));
test('subIv punches a hole', () =>
  assert.deepStrictEqual(subIv([[0, 5]], 1, 2), [[0, 1], [2, 5]]));
test('gapsIv finds scoreboard holes', () =>
  assert.deepStrictEqual(gapsIv([[0, 2], [4, 6]], 0, 6), [[2, 4]]));

test('RACK marks holes behind a SACKed segment once reoWnd elapses', () => {
  const out = run(base([{ t: 10, type: 'ack', cumAck: 1, tsEcho: 0, sacks: [[3, 4]] }], segs(4),
    { mss: 1, initialCwnd: 4, initialSsthresh: 8, reoWndMult: 0.25, timerGranularity: 1, initialRtt: 100 }));
  assert.deepStrictEqual(out.lostSegments.map((x) => x.seq), [1, 2]);
  assert.deepStrictEqual(out.scoreboardHoles, [[1, 3]]);
  assert.strictEqual(out.minRtt, 10);
  assert.strictEqual(out.reoWnd, 2.5);
});
test('no initial RTT sample -> conservative reoWnd, no premature loss', () => {
  const out = run(base([{ t: 10, type: 'ack', cumAck: 1, sacks: [[3, 4]] }], segs(4),
    { mss: 1, initialCwnd: 4, initialSsthresh: 8, reoWndMult: 0.25, timerGranularity: 1, initialRtt: 100 }));
  assert.deepStrictEqual(out.lostSegments, []);
});

test('Eifel timestamp echo detects a spurious retransmit and restores cwnd/ssthresh', () => {
  const out = run(base([
    { t: 10, type: 'ack', cumAck: 1, tsEcho: 0, sacks: [[2, 3]] },
    { t: 20, type: 'ack', cumAck: 2, tsEcho: 1, sacks: [] },
  ], segs(4), { mss: 1, initialCwnd: 4, initialSsthresh: 8, reoWndMult: 0.25, timerGranularity: 1, initialRtt: 100 }));
  assert.strictEqual(out.spuriousRetransmits[0].reason, 'Eifel');
  assert.deepStrictEqual(out.spuriousRetransmits[0].restored, { cwnd: 5, ssthresh: 8 });
  assert.strictEqual(out.inRecovery, false);
});

test('DSACK detects a spurious retransmit of an already-SACKed segment and undoes', () => {
  const out = run(base([
    { t: 10, type: 'ack', cumAck: 1, tsEcho: 0, sacks: [[2, 3]] },
    { t: 12, type: 'rto', seq: 2 },
    { t: 20, type: 'ack', cumAck: 1, tsEcho: 12, sacks: [[2, 3]] },
  ], segs(4), { mss: 1, initialCwnd: 4, initialSsthresh: 8, reoWndMult: 0.25, timerGranularity: 1, initialRtt: 100 }));
  const s = out.spuriousRetransmits.find((x) => x.reason === 'DSACK');
  assert.ok(s);
  assert.strictEqual(s.seq, 2);
  assert.deepStrictEqual(s.restored, { cwnd: 5, ssthresh: 8 });
});

test('partial ACK keeps recovery open and retransmits the next hole', () => {
  const out = run(base([
    { t: 10, type: 'ack', cumAck: 1, tsEcho: 0, sacks: [[3, 4]] },
    { t: 20, type: 'ack', cumAck: 2, tsEcho: 100, sacks: [[3, 4]] },
  ], segs(4), { mss: 1, initialCwnd: 4, initialSsthresh: 8, reoWndMult: 0.25, timerGranularity: 1, initialRtt: 100 }));
  assert.ok(out.trace.some((e) => e.ev === 'partialAck' && e.cumAck === 2));
  assert.strictEqual(out.inRecovery, true);
  assert.deepStrictEqual(out.scoreboardHoles, [[2, 3]]);
});

test('a reneging receiver resurrects a previously SACKed hole', () => {
  const out = run(base([
    { t: 10, type: 'ack', cumAck: 1, tsEcho: 0, sacks: [[2, 4]] },
    { t: 20, type: 'renege', from: 2, to: 3 },
  ], segs(4), { mss: 1, initialCwnd: 4, initialSsthresh: 8, reoWndMult: 0.25, timerGranularity: 1, initialRtt: 100 }));
  assert.ok(out.scoreboardHoles.some(([a, b]) => a <= 2 && b >= 3));
});

test('cumAck inside a SACK block is recorded, scoreboard still covers it', () => {
  const out = run(base([{ t: 10, type: 'ack', cumAck: 2, tsEcho: 0, sacks: [[1, 3]] }], segs(3),
    { mss: 1, initialCwnd: 4, initialSsthresh: 8, reoWndMult: 0.25, timerGranularity: 1, initialRtt: 100 }));
  assert.ok(out.trace.some((e) => e.ev === 'cumAckSackDisagreement'));
  assert.deepStrictEqual(out.scoreboardHoles, []);
});

test('full trace: final cwnd/ssthresh, holes and ordered spurious events', () => {
  const out = run(JSON.parse(fs.readFileSync(__dirname + '/trace_a.json', 'utf8')));
  assert.strictEqual(out.finalCwnd, 2);
  assert.strictEqual(out.finalSsthresh, 2);
  assert.deepStrictEqual(out.scoreboardHoles, [[6, 7]]);
  assert.deepStrictEqual(out.spuriousRetransmits.map((s) => [s.seq, s.reason]), [[1, 'Eifel'], [6, 'DSACK']]);
});

console.log(`\n${passed} tests passed`);
```

